    {{{ oval_metadata("All password hashes should be shadowed.", rule_title=rule_title) }}}









    .*
    state_accounts_password_all_shadowed_has_no_password
    state_accounts_password_all_shadowed_has_locked_password
    state_accounts_password_all_shadowed_sha512
